import socket,ssl,urllib.request,urllib.error,json,time,os
out={'probes':[]}
def try_connect(port):
 t=time.monotonic(); result={'local_port':port}
 try:
  s=socket.create_connection(('127.0.0.1',port),timeout=2);s.settimeout(2)
  s.sendall(b'CONNECT api.telegram.org:443 HTTP/1.1\r\nHost: api.telegram.org:443\r\n\r\n')
  b=s.recv(170)
  result['prefix']=b.decode('latin1','replace').split('\r\n')[0][:100]
 except Exception as e:result['error']=type(e).__name__
 finally:
  try:s.close()
  except:pass
 result['elapsed_ms']=round((time.monotonic()-t)*1000)
 out['probes'].append(result)
for port in (8000,1443):try_connect(port)
try:
 t=time.monotonic()
 opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
 with opener.open('https://api.telegram.org',timeout=5) as response:out['direct_telegram']={'http':response.status,'ms':round((time.monotonic()-t)*1000)}
except urllib.error.HTTPError as e:out['direct_telegram']={'http':e.code}
except Exception as e:out['direct_telegram']={'error':type(e).__name__,'reason_type':str(e.reason.__class__.__name__) if hasattr(e,'reason') else ''}
print(json.dumps(out,ensure_ascii=True))
